--!nolint
-- Rauri
-- A Tauri-shaped app framework for Roblox: reactive UI, a core process with
-- commands and events, a capability manifest and a full icon registry.

local App = __require("src/shared/Rauri/app")
local Components = __require("src/shared/Rauri/components")
local Element = __require("src/shared/Rauri/element")
local Icons = __require("src/shared/Rauri/icons")
local Platform = __require("src/shared/Rauri/platform")
local Signal = __require("src/shared/Rauri/signal")
local Style = __require("src/shared/Rauri/style")
local Theme = __require("src/shared/Rauri/theme")
local Util = __require("src/shared/Rauri/util")
local Web = __require("src/shared/Rauri/web")

local Rauri = {
	version = "0.2.0",

	new = App.new,

	-- reactivity
	signal = Signal.new,
	derive = Signal.derive,
	effect = Signal.effect,
	track = Signal.track,

	-- ui
	ui = Components,
	h = Element.new,
	element = Element,

	-- design + icons
	theme = Theme,
	icons = Icons,

	-- html/css/js frontend and executor support
	web = Web,
	platform = Platform,

	-- helpers
	color = Util.color,
	util = Util,
	style = Style,
}

-- Convenience mount without a core: Rauri.mount(container, function() ... end)
function Rauri.mount(container, render)
	local app = App.new({ name = "Rauri" })
	return app:mount(render, { container = container })
end

return Rauri
end
__modules["src/shared/Rauri/app"] = function()
--!nolint
-- Rauri :: app
-- The "core" side of a Rauri app: commands, events, capabilities and windows.

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")

local Signal = __require("src/shared/Rauri/signal")
local Reconciler = __require("src/shared/Rauri/reconciler")
local Theme = __require("src/shared/Rauri/theme")
local Util = __require("src/shared/Rauri/util")

local App = {}
App.__index = App

local function matches(pattern, command)
	if pattern == "*" then
		return true
	elseif pattern:sub(-1) == "*" then
		return command:sub(1, #pattern - 1) == pattern:sub(1, -2)
	end
	return command == pattern
end

function App.new(config)
	config = config or {}
	return setmetatable({
		name = config.name or "Rauri app",
		version = config.version or "0.1.0",
		capabilities = config.capabilities,
		startedAt = os.clock(),
		_handlers = {},
		_listeners = {},
		_windows = {},
	}, App)
end

function App:handle(command, handler)
	assert(type(command) == "string", "command name must be a string")
	assert(typeof(handler) == "function", "command handler must be a function")
	self._handlers[command] = handler
	return function()
		if self._handlers[command] == handler then
			self._handlers[command] = nil
		end
	end
end

function App:commands()
	local names = {}
	for name in self._handlers do
		table.insert(names, name)
	end
	table.sort(names)
	return names
end

-- A window may call a command when the capability manifest allows it.
-- No manifest means "local development": everything is allowed.
function App:allowed(window, command)
	local caps = self.capabilities
	if caps == nil then
		return true
	end
	for _, pattern in caps.deny or {} do
		if matches(pattern, command) then
			return false
		end
	end
	local allow = {}
	for _, pattern in caps.default or {} do
		table.insert(allow, pattern)
	end
	local scoped = caps.windows and caps.windows[window]
	if scoped then
		for _, pattern in scoped do
			table.insert(allow, pattern)
		end
	end
	for _, pattern in allow do
		if matches(pattern, command) then
			return true
		end
	end
	return false
end

-- Calls a core command. Handlers run synchronously; long work should use
-- task.spawn plus app:emit() to stream results back to the window.
-- Returns (ok, resultOrError).
function App:invoke(command, payload, options)
	options = options or {}
	local window = options.window or "main"
	local handler = self._handlers[command]
	if not handler then
		return false, string.format('unknown command "%s"', command)
	end
	if not self:allowed(window, command) then
		return false, string.format('capability denied: %s (window "%s")', command, window)
	end
	local context = {
		app = self,
		window = window,
		command = command,
		player = options.player or Players.LocalPlayer,
	}
	local ok, result = pcall(handler, payload, context)
	if not ok then
		return false, tostring(result)
	end
	return true, result
end

-- Core -> window event. Listeners are plain callbacks registered by the UI.
function App:emit(event, payload)
	local listeners = self._listeners[event]
	if not listeners then
		return
	end
	for listener in listeners do
		local ok, err = pcall(listener, payload)
		if not ok then
			warn(string.format('[Rauri] "%s" listener failed: %s', event, tostring(err)))
		end
	end
end

function App:listen(event, listener)
	local listeners = self._listeners[event]
	if not listeners then
		listeners = {}
		self._listeners[event] = listeners
	end
	listeners[listener] = true
	return function()
		listeners[listener] = nil
	end
end

function App:uptime()
	return Util.uptime(self.startedAt)
end

-- Mounts a window. The render function is re-run whenever a signal it read
-- changes, then the tree is diffed into Roblox instances.
function App:mount(render, options)
	options = options or {}
	local windowName = options.name or "main"

	local gui
	local createdGui = false
	if options.container then
		gui = options.container
	else
		local parent = options.parent
		if not parent then
			local player = Players.LocalPlayer
			parent = player:WaitForChild("PlayerGui")
		end
		gui = Instance.new("ScreenGui")
		gui.Name = options.guiName or ("Rauri: " .. self.name)
		gui.ResetOnSpawn = false
		gui.IgnoreGuiInset = options.ignoreInset ~= false
		gui.DisplayOrder = options.displayOrder or 50
		gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
		gui.Parent = parent
		createdGui = true
	end
	assert(gui, "[Rauri] mount needs a container or a parent")

	local dirty = false
	local mounted = true
	local markDirty = function()
		dirty = true
	end

	local renderer = Reconciler.mount(gui, function()
		return Signal.track(render, markDirty)
	end)

	local function flush()
		if dirty and mounted then
			dirty = false
			local ok, err = pcall(renderer.draw)
			if not ok then
				warn("[Rauri] render failed: " .. tostring(err))
			end
		end
	end

	local connection
	if RunService then
		connection = RunService.Heartbeat:Connect(flush)
	else
		task.spawn(function()
			while mounted do
				task.wait()
				flush()
			end
		end)
	end

	local unsubscribeTheme = Theme.onChanged(markDirty)

	local handle = {
		name = windowName,
		gui = gui,
		app = self,
	}

	function handle:invalidate()
		dirty = true
	end

	function handle:flush()
		dirty = true
		flush()
	end

	function handle:rerender(fn)
		if fn then
			render = fn
		end
		handle:flush()
	end

	function handle:unmount()
		if not mounted then
			return
		end
		mounted = false
		if connection then
			connection:Disconnect()
		end
		unsubscribeTheme()
		renderer.unmount()
		if createdGui then
			gui:Destroy()
		end
		handle.app._windows[windowName] = nil
	end

	self._windows[windowName] = handle
	return handle
end

function App:window(name)
	return self._windows[name or "main"]
end

function App:destroy()
	for _, window in table.clone(self._windows) do
		window:unmount()
	end
	self._handlers = {}
	self._listeners = {}
end

return App
end
__modules["src/shared/Rauri/signal"] = function()
--!nolint
-- Rauri :: signal
-- Tiny reactive primitives. A render that calls signal:get() subscribes to it,
-- so anything the UI reads is patched automatically when it changes.

local Signal = {}

local activeWatcher = nil

local function notify(watchers)
	for watcher in watchers do
		local ok, err = pcall(watcher)
		if not ok then
			warn("[Rauri] watcher error: " .. tostring(err))
		end
	end
end

function Signal.new(initial)
	local self = {}
	self.value = initial
	self.watchers = {}

	function self:get()
		if activeWatcher then
			self.watchers[activeWatcher] = true
		end
		return self.value
	end

	function self:set(nextValue)
		if self.value == nextValue then
			return nextValue
		end
		self.value = nextValue
		notify(self.watchers)
		return nextValue
	end

	function self:update(transform)
		return self:set(transform(self.value))
	end

	function self:subscribe(watcher)
		self.watchers[watcher] = true
		return function()
			self.watchers[watcher] = nil
		end
	end

	function self:destroy()
		self.watchers = {}
	end

	return self
end

-- Runs fn while every signal read is subscribed to `watcher`.
function Signal.track(fn, watcher)
	local previous = activeWatcher
	activeWatcher = watcher
	local ok, result = pcall(fn)
	activeWatcher = previous
	if not ok then
		error(result, 0)
	end
	return result
end

-- derive(fn, a, b, ...) recomputes whenever one of the dependency signals changes.
function Signal.derive(fn, ...)
	local out = Signal.new(fn())
	for index = 1, select("#", ...) do
		local dependency = select(index, ...)
		if type(dependency) == "table" and dependency.subscribe then
			dependency:subscribe(function()
				out:set(fn())
			end)
		end
	end
	return out
end

function Signal.effect(fn, ...)
	fn()
	for index = 1, select("#", ...) do
		local dependency = select(index, ...)
		if type(dependency) == "table" and dependency.subscribe then
			dependency:subscribe(function()
				fn()
			end)
		end
	end
end

return Signal
end
__modules["src/shared/Rauri/reconciler"] = function()
--!nolint
-- Rauri :: reconciler
-- Resolves a virtual tree (components included) into concrete elements and
-- patches Roblox instances in place. Children are keyed and diffed, so a
-- signal update only rewrites the props that actually changed.

local Props = __require("src/shared/Rauri/props")
local Style = __require("src/shared/Rauri/style")
local Theme = __require("src/shared/Rauri/theme")

local Reconciler = {}

local CLASS = {
	frame = "Frame",
	text = "TextLabel",
	button = "TextButton",
	image = "ImageLabel",
	icon = "ImageLabel",
	scroll = "ScrollingFrame",
	input = "TextBox",
}

local function newMeta()
	return {
		children = {},
		childMetas = {},
		nodes = {},
		handlers = {},
		connections = {},
		style = nil,
		pseudo = nil,
		styleBound = false,
	}
end

local function pushNode(node, out)
	local nodeType = type(node)
	if node == nil or node == false then
		return
	end
	if nodeType == "string" or nodeType == "number" then
		out[#out + 1] = {
			__rauri = true,
			kind = "text",
			props = { text = tostring(node) },
			children = {},
		}
		return
	end
	if nodeType ~= "table" then
		return
	end
	if node.__rauri then
		if typeof(node.kind) == "function" then
			pushNode(node.kind(node.props, node.children), out)
			return
		end
		local children = {}
		for _, child in node.children do
			pushNode(child, children)
		end
		out[#out + 1] = {
			__rauri = true,
			kind = node.kind,
			props = node.props,
			children = children,
			key = node.key or node.props.key,
		}
		return
	end
	for _, child in node do
		pushNode(child, out)
	end
end

local function createInstance(node, padX, padY)
	local className = CLASS[node.kind] or node.kind
	local ok, instance = pcall(Instance.new, className)
	if not ok or not instance then
		error(string.format('[Rauri] unknown element "%s"', tostring(node.kind)), 0)
	end

	if instance:IsA("GuiObject") then
		instance.BorderSizePixel = 0
	end
	if instance:IsA("TextLabel") or instance:IsA("TextButton") or instance:IsA("TextBox") then
		instance.BackgroundTransparency = 1
	end
	if instance:IsA("TextButton") then
		instance.AutoButtonColor = false
		instance.Text = ""
	end
	if instance:IsA("TextBox") then
		instance.ClearTextOnFocus = false
		instance.MultiLine = false
		instance.TextXAlignment = Enum.TextXAlignment.Left
	end
	if node.kind == "scroll" then
		instance.BackgroundTransparency = 1
		instance.BorderSizePixel = 0
		instance.ScrollBarThickness = 4
		instance.ScrollBarImageColor3 = Theme.color("border")
		instance.ScrollingDirection = Enum.ScrollingDirection.Y
		instance.CanvasSize = UDim2.new(0, 0, 0, 0)
		instance.AutomaticCanvasSize = Enum.AutomaticSize.Y
		instance.ClipsDescendants = true
	end
	if node.kind == "icon" then
		instance.BackgroundTransparency = 1
		instance.ScaleType = Enum.ScaleType.Stretch
	end

	local meta = newMeta()
	Props.apply(instance, meta, node.props, node.kind, padX or 0, padY or 0)
	return instance, meta
end

local function nodeKey(node, index)
	return node.key or string.format("%s#%d", tostring(node.kind), index)
end

local diffChildren

local function patchInstance(instance, meta, prevNode, node, padX, padY)
	Props.apply(instance, meta, node.props, node.kind, padX, padY)
	diffChildren(instance, meta, node.children)
end

diffChildren = function(parent, meta, nextNodes)
	local prevNodes = meta.nodes
	local prevInstances = meta.children
	local prevMetas = meta.childMetas

	local existing = {}
	for index, node in prevNodes do
		existing[nodeKey(node, index)] = {
			node = node,
			instance = prevInstances[index],
			meta = prevMetas[index],
			used = false,
		}
	end

	local instances = {}
	local metas = {}
	local padX, padY = Style.paddingSides(meta.style)

	for index, node in nextNodes do
		local record = existing[nodeKey(node, index)]
		local instance, childMeta

		if record and record.node.kind == node.kind and record.instance then
			instance, childMeta = record.instance, record.meta
			record.used = true
			patchInstance(instance, childMeta, record.node, node, padX, padY)
		else
			instance, childMeta = createInstance(node, padX, padY)
			instance.Parent = parent
			diffChildren(instance, childMeta, node.children)
		end

		instances[index] = instance
		metas[index] = childMeta
	end

	for _, record in existing do
		if not record.used and record.instance then
			record.instance:Destroy()
		end
	end

	for index, instance in instances do
		local explicit = nextNodes[index].props.layoutOrder
		if explicit == nil and instance:IsA("GuiObject") then
			instance.LayoutOrder = index
		end
	end

	meta.nodes = nextNodes
	meta.children = instances
	meta.childMetas = metas
end

function Reconciler.mount(container, render)
	local meta = newMeta()

	local function draw()
		local nodes = {}
		pushNode(render(), nodes)
		diffChildren(container, meta, nodes)
	end

	draw()

	return {
		draw = draw,
		unmount = function()
			for _, instance in meta.children do
				instance:Destroy()
			end
			meta.nodes = {}
			meta.children = {}
			meta.childMetas = {}
		end,
	}
end

Reconciler.CLASS = CLASS

return Reconciler
end
__modules["src/shared/Rauri/props"] = function()
--!nolint
-- Rauri :: props
-- Translates element props into Roblox instance properties, styles, layouts,
-- icons and event connections.

local Util = __require("src/shared/Rauri/util")
local Theme = __require("src/shared/Rauri/theme")
local Style = __require("src/shared/Rauri/style")
local Icons = __require("src/shared/Rauri/icons")

local Props = {}

local H_ALIGN = {
	left = Enum.HorizontalAlignment.Left,
	center = Enum.HorizontalAlignment.Center,
	right = Enum.HorizontalAlignment.Right,
	start = Enum.HorizontalAlignment.Left,
	["end"] = Enum.HorizontalAlignment.Right,
}

local V_ALIGN = {
	top = Enum.VerticalAlignment.Top,
	center = Enum.VerticalAlignment.Center,
	bottom = Enum.VerticalAlignment.Bottom,
	start = Enum.VerticalAlignment.Top,
	["end"] = Enum.VerticalAlignment.Bottom,
}

local AUTO_SIZE = {
	none = Enum.AutomaticSize.None,
	x = Enum.AutomaticSize.X,
	y = Enum.AutomaticSize.Y,
	xy = Enum.AutomaticSize.XY,
	both = Enum.AutomaticSize.XY,
}

local EVENT_KEYS = {
	onClick = true,
	onPress = true,
	onRelease = true,
	onHover = true,
	onInput = true,
	onSubmit = true,
	onFocus = true,
	onBlur = true,
	onInputBegan = true,
}

local function set(instance, property, value)
	local current = instance[property]
	if current == value then
		return
	end
	pcall(function()
		instance[property] = value
	end)
end

local function connect(instance, event, fn)
	local signal = instance[event]
	if signal and signal.Connect then
		return signal:Connect(fn)
	end
	return nil
end

local function bindEvent(instance, meta, key)
	local function call(...)
		local fn = meta.handlers[key]
		if not fn then
			return
		end
		local ok, err = pcall(fn, ...)
		if not ok then
			warn("[Rauri] " .. key .. " failed: " .. tostring(err))
		end
	end

	if key == "onClick" then
		meta.connections[key] = connect(instance, "MouseButton1Click", function()
			call(instance)
		end)
	elseif key == "onPress" then
		meta.connections[key] = connect(instance, "MouseButton1Down", function()
			call(instance)
		end)
	elseif key == "onRelease" then
		meta.connections[key] = connect(instance, "MouseButton1Up", function()
			call(instance)
		end)
	elseif key == "onHover" then
		meta.connections[key] = {
			connect(instance, "MouseEnter", function()
				call(true, instance)
			end),
			connect(instance, "MouseLeave", function()
				call(false, instance)
			end),
		}
	elseif key == "onInput" then
		local signal = instance:GetPropertyChangedSignal("Text")
		meta.connections[key] = signal:Connect(function()
			call(instance.Text, instance)
		end)
	elseif key == "onSubmit" then
		meta.connections[key] = connect(instance, "FocusLost", function(enterPressed)
			if enterPressed then
				call(instance.Text, instance)
			end
		end)
	elseif key == "onFocus" then
		meta.connections[key] = connect(instance, "Focused", function()
			call(instance)
		end)
	elseif key == "onBlur" then
		meta.connections[key] = connect(instance, "FocusLost", function()
			call(instance)
		end)
	elseif key == "onInputBegan" then
		meta.connections[key] = connect(instance, "InputBegan", function(input)
			call(input, instance)
		end)
	end
end

local function applyIcon(instance, name, provider)
	local asset = Icons.get(name, provider)
	if not asset then
		set(instance, "Image", "")
		return false
	end
	set(instance, "Image", asset.Image)
	set(instance, "ImageRectSize", asset.RectSize)
	set(instance, "ImageRectOffset", asset.RectOffset)
	return true
end

-- CSS linear gradients become a UIGradient child; CSS 180deg points down,
-- which is UIGradient rotation 90.
local function applyGradient(instance, spec)
	local gradient = instance:FindFirstChild("__rauriGradient")
	if not gradient then
		gradient = Instance.new("UIGradient")
		gradient.Name = "__rauriGradient"
		gradient.Parent = instance
	end
	local from = spec.from or Color3.new(1, 1, 1)
	local to = spec.to or Color3.new(0, 0, 0)
	pcall(function()
		gradient.Color = ColorSequence.new(from, to)
	end)
	set(gradient, "Rotation", (spec.angle or 180) - 90)
end

local function ensureLayout(instance, kind)
	local className = kind == "grid" and "UIGridLayout" or "UIListLayout"
	local layout = instance:FindFirstChild("__rauriLayout")
	if layout and layout.ClassName ~= className then
		layout:Destroy()
		layout = nil
	end
	if not layout then
		layout = Instance.new(className)
		layout.Name = "__rauriLayout"
		layout.Parent = instance
	end
	return layout
end

local function applyLayout(instance, props)
	local kind = props.__layout
	if not kind then
		return
	end
	local style = props.style or {}
	local gap = props.gap
	if gap == nil then
		gap = style.gap or 0
	end
	local layout = ensureLayout(instance, kind)

	if kind == "grid" then
		layout.CellSize = UDim2.fromOffset(props.cell or 112, props.cellHeight or 92)
		layout.CellPadding = UDim2.fromOffset(gap, gap)
		layout.FillDirection = Enum.FillDirection.Horizontal
		layout.HorizontalAlignment = Enum.HorizontalAlignment.Left
		layout.SortOrder = Enum.SortOrder.LayoutOrder
	else
		layout.FillDirection = if kind == "row" then Enum.FillDirection.Horizontal else Enum.FillDirection.Vertical
		layout.Padding = UDim.new(0, gap)
		layout.SortOrder = Enum.SortOrder.LayoutOrder
		local justify = props.justify
		local cross = props.cross
		if kind == "row" then
			layout.HorizontalAlignment = H_ALIGN[justify] or Enum.HorizontalAlignment.Left
			layout.VerticalAlignment = V_ALIGN[cross] or Enum.VerticalAlignment.Top
		else
			layout.VerticalAlignment = V_ALIGN[justify] or Enum.VerticalAlignment.Top
			layout.HorizontalAlignment = H_ALIGN[cross] or Enum.HorizontalAlignment.Left
		end
	end
end

function Props.apply(instance, meta, props, kind, padX, padY)
	-- Dimensions -----------------------------------------------------------
	-- A full-scale child of a padded frame fills the padded box, not the frame.
	if props.size ~= nil then
		local target = Util.size(props.size)
		local x, y = target.X, target.Y
		if padX and padX > 0 and x.Scale == 1 and x.Offset == 0 then
			x = UDim.new(1, -padX)
		end
		if padY and padY > 0 and y.Scale == 1 and y.Offset == 0 then
			y = UDim.new(1, -padY)
		end
		set(instance, "Size", UDim2.new(x.Scale, x.Offset, y.Scale, y.Offset))
	elseif props.width ~= nil or props.height ~= nil then
		local current = instance.Size
		local width = props.width ~= nil and Util.scaleOffset(props.width) or current.X
		local height = props.height ~= nil and Util.scaleOffset(props.height) or current.Y
		if padX and padX > 0 and width.Scale == 1 and width.Offset == 0 then
			width = UDim.new(1, -padX)
		end
		if padY and padY > 0 and height.Scale == 1 and height.Offset == 0 then
			height = UDim.new(1, -padY)
		end
		set(instance, "Size", UDim2.new(width.Scale, width.Offset, height.Scale, height.Offset))
	end
	if props.position ~= nil then
		set(instance, "Position", Util.size(props.position))
	end
	if props.anchor ~= nil then
		local anchor = props.anchor
		if typeof(anchor) == "Vector2" then
			set(instance, "AnchorPoint", anchor)
		elseif anchor == "center" then
			set(instance, "AnchorPoint", Vector2.new(0.5, 0.5))
		elseif type(anchor) == "table" then
			set(instance, "AnchorPoint", Vector2.new(anchor[1] or 0, anchor[2] or 0))
		end
	end
	if props.automaticSize ~= nil then
		set(instance, "AutomaticSize", AUTO_SIZE[props.automaticSize] or props.automaticSize)
	end
	if props.scale ~= nil then
		local uiScale = instance:FindFirstChild("__rauriScale")
		if not uiScale then
			uiScale = Instance.new("UIScale")
			uiScale.Name = "__rauriScale"
			uiScale.Parent = instance
		end
		set(uiScale, "Scale", props.scale)
	end

	-- Stacking and visibility ----------------------------------------------
	if props.visible ~= nil then
		set(instance, "Visible", props.visible ~= false)
	end
	if props.clip ~= nil then
		set(instance, "ClipsDescendants", props.clip == true)
	end
	if props.zIndex ~= nil then
		set(instance, "ZIndex", props.zIndex)
	end
	if props.layoutOrder ~= nil then
		set(instance, "LayoutOrder", props.layoutOrder)
	end
	if props.name ~= nil then
		set(instance, "Name", tostring(props.name))
	end

	-- Content ---------------------------------------------------------------
	if props.text ~= nil then
		set(instance, "Text", tostring(props.text))
	end
	if props.placeholder ~= nil then
		set(instance, "PlaceholderText", tostring(props.placeholder))
	end
	if props.placeholderColor ~= nil then
		set(instance, "PlaceholderColor3", Theme.resolve(props.placeholderColor, Color3.new(0.5, 0.5, 0.55)))
	end
	if props.image ~= nil then
		set(instance, "Image", props.image)
	end
	if props.truncate ~= nil then
		set(instance, "TextTruncate", if props.truncate then Enum.TextTruncate.AtEnd else Enum.TextTruncate.None)
	end
	if props.multiline ~= nil then
		set(instance, "MultiLine", props.multiline == true)
	end
	if props.clearOnFocus ~= nil then
		set(instance, "ClearTextOnFocus", props.clearOnFocus == true)
	end
	if props.active ~= nil then
		set(instance, "Active", props.active == true)
	end
	if props.scrollingEnabled ~= nil then
		set(instance, "ScrollingEnabled", props.scrollingEnabled == true)
	end
	if props.canvasSize ~= nil then
		set(instance, "CanvasSize", Util.size(props.canvasSize))
	end
	if props.automaticCanvasSize ~= nil then
		set(instance, "AutomaticCanvasSize", AUTO_SIZE[props.automaticCanvasSize] or props.automaticCanvasSize)
	end
	if props.scrollBarThickness ~= nil then
		set(instance, "ScrollBarThickness", props.scrollBarThickness)
	end
	if props.scrollBarImageColor3 ~= nil then
		set(instance, "ScrollBarImageColor3", Theme.resolve(props.scrollBarImageColor3, Color3.new(0.2, 0.2, 0.25)))
	end
	if props.lineHeight ~= nil then
		set(instance, "LineHeight", props.lineHeight)
	end
	if props.__gradient ~= nil then
		applyGradient(instance, props.__gradient)
	end

	-- Style -----------------------------------------------------------------
	if props.style ~= nil then
		meta.style = props.style
		Style.bind(instance, meta)
		Style.apply(instance, meta.style, meta.pseudo and meta.style[meta.pseudo] or nil)
	end

	-- Layout ----------------------------------------------------------------
	applyLayout(instance, props)

	-- Icons -----------------------------------------------------------------
	if props.__icon ~= nil then
		applyIcon(instance, props.__icon, props.__iconProvider)
	end

	-- Events ----------------------------------------------------------------
	for key, value in props do
		if EVENT_KEYS[key] then
			meta.handlers[key] = value
			if meta.connections[key] == nil then
				bindEvent(instance, meta, key)
			end
		end
	end
	for key in meta.handlers do
		if props[key] == nil then
			meta.handlers[key] = nil
		end
	end
end

return Props
end
__modules["src/shared/Rauri/util"] = function()
--!nolint
-- Rauri :: util
-- Small helpers shared by the runtime. No Roblox services are required.

local Util = {}

function Util.color(value, fallback)
	if typeof(value) == "Color3" then
		return value
	end
	if type(value) == "string" then
		local hex = value:gsub("^#", "")
		if #hex == 3 then
			hex = hex:gsub(".", "%0%0")
		end
		if #hex == 6 or #hex == 8 then
			local ok, color = pcall(Color3.fromHex, "#" .. hex:sub(1, 6))
			if ok then
				return color
			end
		end
	end
	return fallback or Color3.new(1, 1, 1)
end

-- Accepts a UDim, a number (offset), a { scale, offset } pair, or "fill".
function Util.scaleOffset(value)
	if typeof(value) == "UDim" then
		return value
	end
	if type(value) == "number" then
		return UDim.new(0, value)
	end
	if value == "fill" then
		return UDim.new(1, 0)
	end
	if type(value) == "table" then
		return UDim.new(value[1] or value.scale or 0, value[2] or value.offset or 0)
	end
	return UDim.new(0, 0)
end

-- Accepts a UDim2, a { xScale, xOffset, yScale, yOffset } table, or keywords:
-- "fill", "fillx", "filly".
function Util.size(value)
	if typeof(value) == "UDim2" then
		return value
	end
	if value == "fill" then
		return UDim2.fromScale(1, 1)
	elseif value == "fillx" then
		return UDim2.new(1, 0, 0, 0)
	elseif value == "filly" then
		return UDim2.new(0, 0, 1, 0)
	end
	if type(value) == "table" then
		if value.X ~= nil and value.Y ~= nil then
			return UDim2.new(value.X.Scale, value.X.Offset, value.Y.Scale, value.Y.Offset)
		end
		return UDim2.new(value[1] or 0, value[2] or 0, value[3] or 0, value[4] or 0)
	end
	return UDim2.new(0, 0, 0, 0)
end

function Util.merge(base, patch)
	local out = {}
	for key, value in base or {} do
		out[key] = value
	end
	for key, value in patch or {} do
		out[key] = value
	end
	return out
end

function Util.shallowEqual(a, b)
	if a == b then
		return true
	end
	if type(a) ~= "table" or type(b) ~= "table" then
		return false
	end
	for key, value in a do
		if b[key] ~= value then
			return false
		end
	end
	for key in b do
		if a[key] == nil then
			return false
		end
	end
	return true
end

function Util.clamp(value, min, max)
	if value < min then
		return min
	elseif value > max then
		return max
	end
	return value
end

function Util.truncate(text, limit)
	text = tostring(text or "")
	if #text <= limit then
		return text
	end
	return text:sub(1, math.max(1, limit - 1)) .. "…"
end

function Util.now()
	return os.clock()
end

function Util.uptime(startedAt)
	local seconds = math.max(0, os.clock() - startedAt)
	if seconds < 60 then
		return string.format("%ds", math.floor(seconds))
	elseif seconds < 3600 then
		return string.format("%dm %ds", math.floor(seconds / 60), math.floor(seconds % 60))
	end
	return string.format("%dh %dm", math.floor(seconds / 3600), math.floor((seconds % 3600) / 60))
end

-- "14:03:22"
function Util.clock()
	local seconds = math.floor(os.clock() % 86400)
	return string.format("%02d:%02d:%02d", math.floor(seconds / 3600), math.floor((seconds % 3600) / 60), seconds % 60)
end

return Util
end
__modules["src/shared/Rauri/theme"] = function()
--!nolint
-- Rauri :: theme
-- Design tokens. Style values can reference a token with "$name".
-- Reading tokens during a render subscribes that window to theme changes.

local Signal = __require("src/shared/Rauri/signal")
local Util = __require("src/shared/Rauri/util")

local DEFAULT = {
	bg = "#0b0b0f",
	panel = "#121218",
	surface = "#181820",
	surfaceAlt = "#22222c",
	border = "#2c2c3a",
	text = "#ececf3",
	muted = "#8a8a9e",
	accent = "#6d6dfb",
	accentText = "#ffffff",
	danger = "#f0637a",
	success = "#43c78f",
	warn = "#f4b740",
	radius = 10,
	pad = 12,
	gap = 8,
}

local tokens = Signal.new(table.clone(DEFAULT))

local Theme = {}

function Theme.get(name)
	return tokens:get()[name]
end

function Theme.tokens()
	return tokens:get()
end

function Theme.set(values)
	local nextTokens = table.clone(tokens:get())
	for key, value in values do
		nextTokens[key] = value
	end
	tokens:set(nextTokens)
end

function Theme.setToken(name, value)
	Theme.set({ [name] = value })
end

function Theme.reset()
	tokens:set(table.clone(DEFAULT))
end

function Theme.onChanged(fn)
	return tokens:subscribe(fn)
end

-- Resolves "#6d6dfb", "$accent", or a Color3 into a Color3.
function Theme.resolve(value, fallback)
	if type(value) == "string" and value:sub(1, 1) == "$" then
		return Util.color(tokens:get()[value:sub(2)], fallback)
	end
	return Util.color(value, fallback)
end

function Theme.color(name, fallback)
	return Util.color(tokens:get()[name], fallback)
end

Theme.defaults = DEFAULT

return Theme
end
__modules["src/shared/Rauri/style"] = function()
--!nolint
-- Rauri :: style
-- Applies a style table to a Roblox GuiObject: colors, fonts, radius,
-- padding, borders, plus hover/press variants.

local Util = __require("src/shared/Rauri/util")
local Theme = __require("src/shared/Rauri/theme")

local Style = {}

local FONTS = {
	regular = Enum.Font.Gotham,
	medium = Enum.Font.GothamMedium,
	semibold = Enum.Font.GothamSemibold,
	bold = Enum.Font.GothamBold,
	black = Enum.Font.GothamBlack,
	mono = Enum.Font.RobotoMono,
}

local X_ALIGN = {
	left = Enum.TextXAlignment.Left,
	center = Enum.TextXAlignment.Center,
	right = Enum.TextXAlignment.Right,
}

local Y_ALIGN = {
	top = Enum.TextYAlignment.Top,
	center = Enum.TextYAlignment.Center,
	bottom = Enum.TextYAlignment.Bottom,
}

local function set(instance, property, value)
	if instance[property] ~= value then
		instance[property] = value
	end
end

local function ensure(instance, className, name)
	local child = instance:FindFirstChild(name)
	if not child then
		child = Instance.new(className)
		child.Name = name
		child.Parent = instance
	end
	return child
end

-- Returns top, right, bottom, left.
local function sides(value)
	if type(value) == "number" then
		return value, value, value, value
	end
	if type(value) == "table" then
		if value.top or value.right or value.bottom or value.left then
			return value.top or 0, value.right or 0, value.bottom or 0, value.left or 0
		end
		local horizontal = value[1] or value.x or 0
		local vertical = value[2] or value.y or 0
		return vertical, horizontal, vertical, horizontal
	end
	return 0, 0, 0, 0
end

local function cornerRadius(value)
	if type(value) == "number" then
		return UDim.new(0, value)
	end
	if type(value) == "table" then
		return UDim.new(value[1] or value.scale or 0, value[2] or value.offset or 0)
	end
	return UDim.new(0, 0)
end

function Style.apply(instance, style, variant)
	style = style or {}
	if variant then
		style = Util.merge(style, variant)
	end

	if not instance:IsA("GuiObject") then
		return
	end

	if style.bg == nil or style.bg == false then
		set(instance, "BackgroundTransparency", 1)
	else
		set(instance, "BackgroundColor3", Theme.resolve(style.bg, Color3.new(0.07, 0.07, 0.1)))
		set(instance, "BackgroundTransparency", style.bgAlpha or 0)
	end

	local isText = instance:IsA("TextLabel") or instance:IsA("TextButton") or instance:IsA("TextBox")
	if isText then
		if style.fg then
			set(instance, "TextColor3", Theme.resolve(style.fg, Color3.new(1, 1, 1)))
		end
		if style.fontSize then
			set(instance, "TextSize", style.fontSize)
		end
		if style.font then
			set(instance, "Font", FONTS[style.font] or style.font)
		end
		if style.align then
			set(instance, "TextXAlignment", X_ALIGN[style.align] or Enum.TextXAlignment.Left)
		end
		if style.valign then
			set(instance, "TextYAlignment", Y_ALIGN[style.valign] or Enum.TextYAlignment.Center)
		end
		if style.wrap ~= nil then
			set(instance, "TextWrapped", style.wrap == true)
		end
		if style.rich ~= nil then
			set(instance, "RichText", style.rich == true)
		end
	end

	if instance:IsA("ImageLabel") and style.fg then
		set(instance, "ImageColor3", Theme.resolve(style.fg, Color3.new(1, 1, 1)))
	end

	local corner = instance:FindFirstChild("__rauriCorner")
	if style.radius ~= nil then
		if not corner then
			corner = ensure(instance, "UICorner", "__rauriCorner")
		end
		set(corner, "CornerRadius", cornerRadius(style.radius))
	elseif corner then
		set(corner, "CornerRadius", UDim.new(0, 0))
	end

	local padding = instance:FindFirstChild("__rauriPadding")
	if style.pad ~= nil then
		if not padding then
			padding = ensure(instance, "UIPadding", "__rauriPadding")
		end
		local top, right, bottom, left = sides(style.pad)
		set(padding, "PaddingTop", UDim.new(0, top))
		set(padding, "PaddingRight", UDim.new(0, right))
		set(padding, "PaddingBottom", UDim.new(0, bottom))
		set(padding, "PaddingLeft", UDim.new(0, left))
	elseif padding then
		set(padding, "PaddingTop", UDim.new(0, 0))
		set(padding, "PaddingRight", UDim.new(0, 0))
		set(padding, "PaddingBottom", UDim.new(0, 0))
		set(padding, "PaddingLeft", UDim.new(0, 0))
	end

	local stroke = instance:FindFirstChild("__rauriStroke")
	if style.border ~= nil and style.border ~= false then
		if not stroke then
			stroke = ensure(instance, "UIStroke", "__rauriStroke")
		end
		local thickness, color = 1, "$border"
		if type(style.border) == "number" then
			thickness = style.border
		elseif type(style.border) == "table" then
			thickness = style.border[1] or style.border.width or 1
			color = style.border[2] or style.border.color or "$border"
		end
		set(stroke, "Thickness", thickness)
		set(stroke, "Color", Theme.resolve(color, Color3.new(0.2, 0.2, 0.25)))
		set(stroke, "ApplyStrokeMode", Enum.ApplyStrokeMode.Border)
	elseif stroke then
		set(stroke, "Thickness", 0)
	end
end

local function connect(instance, event, fn)
	local signal = instance[event]
	if signal and signal.Connect then
		return signal:Connect(fn)
	end
	return nil
end

-- Connects hover/press variants once per instance.
function Style.bind(instance, meta)
	if meta.styleBound then
		return
	end
	meta.styleBound = true

	local function show(state)
		if not meta.style then
			return
		end
		meta.pseudo = state
		Style.apply(instance, meta.style, state and meta.style[state] or nil)
	end

	connect(instance, "MouseEnter", function()
		show("hover")
	end)
	connect(instance, "MouseLeave", function()
		show(nil)
	end)
	connect(instance, "MouseButton1Down", function()
		show("press")
	end)
	connect(instance, "MouseButton1Up", function()
		show("hover")
	end)
end

Style.FONTS = FONTS

-- Total padding on each axis, used to turn "fill" into a padded fill.
function Style.paddingSides(style)
	if not style or style.pad == nil then
		return 0, 0
	end
	local top, right, bottom, left = sides(style.pad)
	return left + right, top + bottom
end

return Style
end
__modules["src/shared/Rauri/icons"] = function()
--!nolint
-- Rauri :: icons
-- Icon registry adapter for Molto (https://molto.pages.dev).
--
-- Molto publishes one sprite sheet per provider. Its glyphs are white on
-- transparent, so a sprite can be tinted with ImageColor3 like any font glyph.
-- Rauri bundles a curated set of each provider so icons render in Studio and in
-- live games; when the framework runs under an executor (loadstring + HttpGet),
-- the full 64k icon registry is loaded from molto and used instead.

local IconData = __require("src/shared/Rauri/iconsData")

local Icons = {}

local REMOTE_URL = "https://molto.pages.dev/source.lua"
local DEFAULT_PROVIDER = "lucide"

local current = DEFAULT_PROVIDER
local remote = nil -- nil: not tried, false: unavailable, table: loaded registry
local listeners = {}

local PROVIDER_ORDER = { "lucide", "tabler", "heroicons", "phosphor", "fluent", "solar", "material" }

local function registry()
	if remote ~= nil then
		return remote
	end
	remote = false
	if typeof(loadstring) ~= "function" then
		return false
	end
	local okHttp, httpGet = pcall(function()
		return game.HttpGet
	end)
	if not okHttp or typeof(httpGet) ~= "function" then
		return false
	end
	local ok, result = pcall(function()
		return loadstring(httpGet(game, REMOTE_URL))()
	end)
	if ok and type(result) == "table" and typeof(result.GetAsset) == "function" then
		remote = result
	end
	return remote
end

-- Loads the full icon registry from molto. Requires an executor that provides
-- loadstring and game:HttpGet. Returns true when the registry is available.
function Icons.loadRemote()
	return registry() ~= false
end

function Icons.remoteAvailable()
	return registry() ~= false
end

function Icons.ORDER()
	return table.clone(PROVIDER_ORDER)
end

function Icons.providers()
	local list = {}
	for _, id in PROVIDER_ORDER do
		local data = IconData[id]
		if data then
			table.insert(list, {
				id = id,
				name = data.Name,
				count = data.Count,
				license = data.License,
				bundled = #data.Order,
			})
		end
	end
	return list
end

function Icons.getProvider()
	return current
end

function Icons.setProvider(id)
	local ok = IconData[id] ~= nil
	local reg = registry()
	if reg then
		local success = pcall(reg.SetProvider, id)
		ok = ok or success
		if not success then
			return false
		end
	elseif not ok then
		return false
	end
	current = id
	for listener in listeners do
		local success, err = pcall(listener, id)
		if not success then
			warn("[Rauri] icon provider listener failed: " .. tostring(err))
		end
	end
	return true
end

function Icons.onProviderChanged(fn)
	listeners[fn] = true
	return function()
		listeners[fn] = nil
	end
end

-- Names available for a provider. Full list under an executor, bundled sample otherwise.
function Icons.list(provider)
	provider = provider or current
	local reg = registry()
	if reg then
		local ok, names = pcall(reg.GetIcons, provider)
		if ok and type(names) == "table" then
			return names
		end
	end
	local data = IconData[provider]
	return data and data.Order or {}
end

-- Returns { Name, Provider, Image, RectSize, RectOffset, FontFace, Text } or nil.
function Icons.get(name, provider)
	if type(name) ~= "string" or name == "" then
		return nil
	end
	provider = provider or current

	local reg = registry()
	if reg then
		local ok, asset = pcall(reg.GetAsset, name, provider)
		if ok and type(asset) == "table" and asset.Url then
			return {
				Name = asset.IconName or name,
				Provider = provider,
				Image = asset.Url,
				RectSize = asset.ImageRectSize,
				RectOffset = asset.ImageRectOffset,
				FontFace = asset.FontFace,
				Text = asset.Text,
			}
		end
	end

	local data = IconData[provider]
	if not data then
		return nil
	end
	local resolved = name
	for _ = 1, 8 do
		local alias = data.Aliases and data.Aliases[resolved]
		if not alias then
			break
		end
		resolved = alias
	end
	local entry = data.Icons[resolved]
	if not entry then
		return nil
	end
	return {
		Name = resolved,
		Provider = provider,
		Image = data.Sheets[entry[1]],
		RectSize = Vector2.new(entry[2], entry[3]),
		RectOffset = Vector2.new(entry[4], entry[5]),
	}
end

function Icons.has(name, provider)
	return Icons.get(name, provider) ~= nil
end

function Icons.search(query, limit, provider)
	provider = provider or current
	limit = limit or 60
	local names = Icons.list(provider)
	local needle = tostring(query or ""):lower():gsub("^%s+", ""):gsub("%s+$", "")

	local results = {}
	if needle == "" then
		for index = 1, math.min(limit, #names) do
			results[index] = names[index]
		end
		return results, #names
	end
	for _, name in names do
		if #results >= limit then
			break
		end
		if name:find(needle, 1, true) then
			table.insert(results, name)
		end
	end
	return results, #names
end

function Icons.info(provider)
	provider = provider or current
	local data = IconData[provider]
	local total = data and data.Count or 0
	local bundled = data and #data.Order or 0
	if data == nil then
		-- Provider only known to the remote registry.
		total = #Icons.list(provider)
	end
	local reg = registry()
	if reg then
		local ok, info = pcall(reg.GetProviderInfo, provider)
		if ok and type(info) == "table" then
			total = info.Count or total
		end
	end
	return {
		id = provider,
		name = data and data.Name or provider,
		count = total,
		bundled = bundled,
		license = data and data.License or "",
		remote = reg ~= false,
	}
end

-- Applies an icon to an ImageLabel (sprite) or TextLabel (font, when the
-- executor registry provides a FontFace).
function Icons.apply(label, name, color)
	local asset = Icons.get(name)
	if not asset then
		if label:IsA("ImageLabel") then
			label.Image = ""
		end
		return false
	end
	if label:IsA("TextLabel") and not label:IsA("TextBox") then
		if asset.FontFace then
			label.Text = asset.Text
			label.FontFace = asset.FontFace
			if color then
				label.TextColor3 = color
			end
			return true
		end
		return false
	end
	if label:IsA("ImageLabel") then
		label.Image = asset.Image
		label.ImageRectSize = asset.RectSize
		label.ImageRectOffset = asset.RectOffset
		if color then
			label.ImageColor3 = color
		end
		return true
	end
	return false
end

function Icons.preload(names)
	local reg = registry()
	if reg and typeof(reg.PreloadAsync) == "function" then
		local ok, ready = pcall(reg.PreloadAsync, names, current)
		if ok then
			return ready
		end
	end
	return 0
end

Icons.DEFAULT_PROVIDER = DEFAULT_PROVIDER
Icons.REMOTE_URL = REMOTE_URL

return Icons
end
__modules["src/shared/Rauri/iconsData"] = function()
-- Generated from molto.pages.dev provider data (https://molto.pages.dev/).
-- Glyphs are white on transparent sprite sheets, so they tint through ImageColor3.
-- Bundled sets are curated samples; the full registry is loaded from molto when an executor is available.
return {
	lucide = {
		Name = "Lucide",
		Count = 2095,
		License = "ISC",
		Sheets = {
			[1] = "rbxassetid://118199753695009",
			[2] = "rbxassetid://105958624998202",
		},
