__modules["src/shared/Rauri/platform"] = function()
--!nolint
-- Rauri :: platform
-- Exposes the extra capabilities executor environments provide: gethui parents,
-- GUI protection, clipboard and file IO. Everything degrades gracefully in
-- Studio and in games where only the framework ships.

local Players = game:GetService("Players")

local Platform = {}

local function globalFunction(name)
	local value = rawget(_G, name)
	if value == nil then
		value = rawget(getfenv(0), name)
	end
	return typeof(value) == "function"
end

-- True when executor-only globals are present. No vendor sniffing: a plain
-- capability check is enough to pick the right parent and helpers.
function Platform.isExecutor()
	return globalFunction("gethui") or globalFunction("setclipboard") or globalFunction("readfile")
end

-- The safest container for a Rauri UI: gethui when available (executors keep
-- it above the game and outside detection), PlayerGui otherwise so Studio and
-- headless tests keep working.
function Platform.guiParent()
	if globalFunction("gethui") then
		local ok, parent = pcall(gethui)
		if ok and typeof(parent) == "Instance" then
			return parent
		end
	end

	local player = Players and Players.LocalPlayer
	if player then
		local playerGui = player:FindFirstChild("PlayerGui")
		if playerGui then
			return playerGui
		end
		local ok, waited = pcall(function()
			return player:WaitForChild("PlayerGui", 5)
		end)
		if ok and waited then
			return waited
		end
	end
	return nil
end

-- Prevents executors and games from destroying the ScreenGui easily.
function Platform.protect(gui)
	if gui == nil or not globalFunction("protect_gui") then
		return false
	end
	return pcall(protect_gui, gui)
end

function Platform.setClipboard(text)
	text = tostring(text or "")
	if globalFunction("setclipboard") then
		return pcall(setclipboard, text)
	end
	if globalFunction("toclipboard") then
		return pcall(toclipboard, text)
	end
	return false
end

function Platform.readFile(path)
	if globalFunction("readfile") then
		local ok, contents = pcall(readfile, tostring(path))
		return ok and contents or nil
	end
	return nil
end

function Platform.writeFile(path, contents)
	if globalFunction("writefile") then
		return pcall(writefile, tostring(path), tostring(contents))
	end
	return false
end

function Platform.fileExists(path)
	if globalFunction("isfile") then
		local ok, exists = pcall(isfile, tostring(path))
		return ok and exists == true
	end
	return false
end

function Platform.listFiles(path)
	if globalFunction("listfiles") then
		local ok, files = pcall(listfiles, tostring(path or ""))
		if ok and type(files) == "table" then
			return files
		end
	end
	return {}
end

function Platform.httpGet(url)
	if typeof(game.HttpGet) == "function" then
		local ok, body = pcall(function()
			return game:HttpGet(tostring(url))
		end)
		if ok then
			return body
		end
	end
	return nil
end

function Platform.notify(title, text)
	local ok, starterGui = pcall(function()
		return game:GetService("StarterGui")
	end)
	if not ok or not starterGui then
		return false
	end
	local success = pcall(function()
		starterGui:SetCore("SendNotification", {
			Title = tostring(title or "Rauri"),
			Text = tostring(text or ""),
			Duration = 3,
		})
	end)
	return success
end

function Platform.summary()
	return {
		executor = Platform.isExecutor(),
		clipboard = globalFunction("setclipboard") or globalFunction("toclipboard"),
		fileIO = (globalFunction("readfile") and globalFunction("writefile")) or false,
		http = typeof(game.HttpGet) == "function",
	}
end

return Platform
end
__modules["src/shared/Rauri/web"] = function()
--!nolint
-- Rauri :: web
-- Bring the web to Roblox: parse HTML/CSS, lay it out, render it with Rauri
-- elements and run JavaScript against a DOM. This is what lets script
-- developers write UI once in HTML/CSS/JS and load it in an executor.
--
--   local Rauri = loadstring(game:HttpGet(
--     "https://raw.githubusercontent.com/sickletone/project-rauri/main/dist/rauri.lua"
--   ))()
--   Rauri.web.app({ title = "My Hub", html = [[ ... ]], css = [[ ... ]], js = [[ ... ]] })

local Html = __require("src/shared/Rauri/web/html")
local Css = __require("src/shared/Rauri/web/css")
local Dom = __require("src/shared/Rauri/web/dom")
local Layout = __require("src/shared/Rauri/web/layout")
local Render = __require("src/shared/Rauri/web/render")
local Js = __require("src/shared/Rauri/web/js")
local Bindings = __require("src/shared/Rauri/web/bindings")

local Signal = __require("src/shared/Rauri/signal")
local App = __require("src/shared/Rauri/app")
local Components = __require("src/shared/Rauri/components")
local Platform = __require("src/shared/Rauri/platform")

local Web = {}
Web.__index = Web

Web.version = "0.2.0"

local BASE_CSS = [[
* { box-sizing: border-box; }
:root {
  --bg: #0b0b0f;
  --panel: #121218;
  --surface: #181820;
  --surface-alt: #22222c;
  --border: #2c2c3a;
  --text: #ececf3;
  --muted: #8a8a9e;
  --accent: #6d6dfb;
  --accent-text: #ffffff;
  --danger: #f0637a;
  --success: #43c78f;
  --radius: 12px;
}
body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  background: var(--bg);
  color: var(--text);
  font-size: 13px;
  font-family: sans-serif;
  overflow: hidden;
}
h1 { font-size: 22px; font-weight: 700; margin: 0 0 8px 0; }
h2 { font-size: 17px; font-weight: 600; margin: 0 0 8px 0; }
h3 { font-size: 14px; font-weight: 600; margin: 0 0 6px 0; }
p { margin: 0 0 8px 0; }
a { color: var(--accent); }
code { font-family: mono; background: var(--surface); color: var(--text); }
button {
  border-radius: 8px;
  background: var(--surface-alt);
  color: var(--text);
  padding: 7px 12px;
  font-size: 13px;
  font-weight: 500;
}
button:hover { background: var(--border); }
button:active { background: var(--surface); }
input, textarea, select {
  background: var(--panel);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 7px 10px;
  font-size: 13px;
}
table { border: 1px solid var(--border); border-radius: 8px; overflow: hidden; }
tr { border-bottom: 1px solid var(--border); }
tr:last-child { border-bottom: 0; }
td, th { flex: 1; padding: 6px 8px; }
th { font-weight: 700; }
select { min-width: 120px; }
textarea { min-width: 200px; min-height: 60px; }
summary { font-weight: 600; }
details:not([open]) > *:not(summary) { display: none; }
hr { height: 1px; background: var(--border); border: 0; margin: 12px 0; }
progress { height: 8px; background: var(--surface-alt); border-radius: 999px; overflow: hidden; }
label { margin-right: 6px; }
input::placeholder { color: var(--muted); }
.rauri-window {
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  background: var(--bg);
  border-radius: var(--radius);
  overflow: hidden;
}
.rauri-titlebar {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  height: 38px;
  padding: 0 12px;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}
.rauri-title {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
  color: var(--text);
  font-size: 12px;
  font-weight: 600;
}
.rauri-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--accent);
}
.rauri-controls {
  display: flex;
  flex-direction: row;
  gap: 4px;
}
.rauri-controls button {
  width: 24px;
  height: 20px;
  border-radius: 5px;
  background: transparent;
  color: var(--muted);
  font-size: 13px;
  padding: 0;
}
.rauri-controls button:hover { background: var(--surface-alt); color: var(--text); }
.rauri-close:hover { background: var(--danger); color: white; }
.rauri-body {
  flex: 1;
  overflow-y: auto;
  padding: 14px;
}
.rauri-empty {
  color: var(--muted);
  font-size: 13px;
}
]]

local DEFAULT_VARS = {
	["--bg"] = "#0b0b0f",
	["--panel"] = "#121218",
	["--surface"] = "#181820",
	["--surface-alt"] = "#22222c",
	["--border"] = "#2c2c3a",
	["--text"] = "#ececf3",
	["--muted"] = "#8a8a9e",
	["--accent"] = "#6d6dfb",
	["--accent-text"] = "#ffffff",
	["--danger"] = "#f0637a",
	["--success"] = "#43c78f",
	["--radius"] = "12px",
}

local function chromeMarkup(title, body)
	return string.format([[
<div class="rauri-window">
  <div class="rauri-titlebar" data-drag="true">
    <div class="rauri-title"><span class="rauri-dot"></span><span>%s</span></div>
    <div class="rauri-controls">
      <button class="rauri-min" data-action="minimize" title="Minimize">-</button>
      <button class="rauri-close" data-action="close" title="Close">x</button>
    </div>
  </div>
  <div class="rauri-body">%s</div>
</div>]], tostring(title or "Rauri"), body)
end

local function toCssValue(value, isRadius)
	if type(value) == "number" then
		return tostring(value) .. "px"
	end
	return tostring(value)
end

function Web.new(config)
	config = config or {}
	local self = setmetatable({}, Web)
	self.config = config
	self.width = config.width or 760
	self.height = config.height or 520
	self.radius = config.radius or 12
	self.version = Signal.new(0)
	self.position = Signal.new(UDim2.new(0.5, 0, 0.5, 0))
	self.minimized = Signal.new(false)
	self.toasts = Signal.new({})
	self.storage = {}
	self.boxById = {}
	self.toastCounter = 0
	self.closed = false
	self.vars = {}

	for name, value in DEFAULT_VARS do
		self.vars[name] = value
	end
	self.vars["--radius"] = tostring(self.radius) .. "px"
	for name, value in config.theme or {} do
		name = tostring(name)
		if name:sub(1, 2) ~= "--" then
			name = "--" .. name
		end
		self.vars[name] = toCssValue(value)
	end

	self:build(config)
	return self
end

function Web:build(config)
	local html = config.html
	if not html and config.url then
		html = Platform.httpGet(config.url)
		if not html then
			html = '<div class="rauri-empty">Could not load ' .. tostring(config.url) .. '</div>'
		end
	end
	html = html or '<div class="rauri-empty">Rauri web</div>'
	if config.chrome ~= false then
		html = chromeMarkup(config.title or "Rauri", html)
	end

	self.document = Dom.newDocument(html)
	self.document.onChange = function()
		self:invalidate()
	end

	self.scripts = {}
	for _, scriptNode in Dom.querySelectorAll(self.document, "script") do
		local source = Html.flattenText(scriptNode)
		local src = scriptNode.attrs.src
		if src and src ~= "" then
			if Platform.isExecutor() then
				local body = Platform.httpGet(src)
				if body then
					self.scripts[#self.scripts + 1] = body
				end
			end
		elseif source ~= "" then
			self.scripts[#self.scripts + 1] = source
		end
	end

	self.styleTags = ""
	for _, styleNode in Dom.querySelectorAll(self.document, "style") do
		self.styleTags = self.styleTags .. "\n" .. Html.flattenText(styleNode)
	end
	-- Remote stylesheets are fetched in executors (game:HttpGet); elsewhere
	-- they are ignored, like an offline browser.
	for _, linkNode in Dom.querySelectorAll(self.document, "link") do
		local href = linkNode.attrs.href
		local rel = (linkNode.attrs.rel or ""):lower()
		if href and rel == "stylesheet" and Platform.isExecutor() then
			local body = Platform.httpGet(href)
			if body then
				self.styleTags = self.styleTags .. "\n" .. body
			end
		end
	end

	self:rebuildStyles()
end

function Web:themeCss()
	local parts = { ":root {" }
	for name, value in self.vars do
		if name:sub(1, 2) == "--" then
			parts[#parts + 1] = name .. ": " .. tostring(value) .. ";"
		end
	end
	parts[#parts + 1] = "}"
	return table.concat(parts, "\n")
end

function Web:rebuildStyles()
	local css = BASE_CSS .. "\n" .. self:themeCss() .. "\n" .. self.styleTags .. "\n" .. (self.config.css or "")
	self.stylesheet = Css.parse(css, { width = self.width })
	self.hoverable = css:find(":hover", 1, true) ~= nil
end

function Web:invalidate()
	self.version:update(function(value)
		return value + 1
	end)
end

function Web:log(message)
	message = tostring(message)
	if self.config.onLog then
		pcall(self.config.onLog, message)
	else
		warn("[Rauri web] " .. message)
	end
end

function Web:var(name)
	name = tostring(name or "")
	if name:sub(1, 2) ~= "--" then
		name = "--" .. name
	end
	return self.vars[name] or DEFAULT_VARS[name] or ""
end

function Web:setVar(name, value)
	name = tostring(name or "")
	if name:sub(1, 2) ~= "--" then
		name = "--" .. name
	end
	self.vars[name] = toCssValue(value)
	self:rebuildStyles()
	self:invalidate()
end

function Web:boxOf(node)
	if not node then
		return nil
	end
	return self.boxById[node.id]
end

function Web:start()
	if self.started then
		return
	end
	self.started = true

	self.host, self.wrap, self.unwrap = Bindings.create(self)

	local sources = {}
	local configJs = self.config.js
	if type(configJs) == "table" then
		for _, source in configJs do
			sources[#sources + 1] = source
		end
	elseif configJs then
		sources[#sources + 1] = configJs
	end
	for _, source in self.scripts do
		sources[#sources + 1] = source
	end

	for _, source in sources do
		local ok, err = Js.run(source, self.host)
		if not ok then
			self:log(err)
		end
	end
end

function Web:notify(message, duration)
	self.toastCounter += 1
	local id = self.toastCounter
	local list = table.clone(self.toasts:get())
	list[#list + 1] = { id = id, message = tostring(message or "") }
	self.toasts:set(list)

	task.delay(duration or 2.6, function()
		local current = {}
		for _, toast in self.toasts:get() do
			if toast.id ~= id then
				current[#current + 1] = toast
			end
		end
		self.toasts:set(current)
	end)
end

function Web:setHover(node, hovered)
	if node.state.hover == hovered then
		return
	end
	node.state.hover = hovered
	self:invalidate()
end

function Web:setActive(node, active)
	if node.state.active == active then
		return
	end
	node.state.active = active
	self:invalidate()
end

function Web:dispatch(node, eventType, detail)
	detail = detail or {}
	local wrap = self.wrap or function(value)
		return value
	end
	local event = {
		type = eventType,
		target = wrap(node),
		currentTarget = wrap(node),
		value = detail.value,
		key = detail.key,
		action = detail.action,
	}
	function event.stopPropagation()
		event.propagationStopped = true
	end
	function event.preventDefault()
		event.defaultPrevented = true
	end

	local current = node
	while current do
		event.currentTarget = wrap(current)
		local listeners = current.listeners[eventType]
		if listeners then
			for _, listener in table.clone(listeners) do
				local ok, err = pcall(listener, event)
				if not ok then
					self:log("listener error: " .. tostring(err))
				end
			end
		end
		if event.propagationStopped then
			break
		end
		current = current.parent
	end
end

function Web:action(name)
	if name == "close" then
		self:close()
	elseif name == "minimize" then
		self.minimized:set(true)
	elseif name == "restore" then
		self.minimized:set(false)
	else
		self:dispatch(self.document.body, "action", { action = name })
	end
end

function Web:click(node)
	local action = node.attrs["data-action"]
	if action then
		self:action(action)
	end
	local tag = node.tag
	local inputType = tag == "input" and (node.attrs.type or "text"):lower() or nil
	if tag == "summary" and node.parent and node.parent.tag == "details" then
		local details = node.parent
		details.attrs.open = details.attrs.open ~= nil and nil or ""
		self:invalidate()
	elseif tag == "label" and node.attrs["for"] then
		local target = Dom.querySelector(self.document, "#" .. node.attrs["for"])
		if target and target ~= node then
			if target.tag == "input" then
				target.state.focus = true
				self:invalidate()
			else
				self:click(target)
			end
		end
	elseif tag == "select" then
		local options = {}
		for _, child in node.children do
			if child.type == "element" and child.tag == "option" then
				options[#options + 1] = child
			end
		end
		if #options > 0 then
			local index = 1
			for position, option in options do
				local value = option.attrs.value or Html.flattenText(option)
				if option.attrs.selected ~= nil or (node.value ~= nil and node.value == value) then
					index = position
					break
				end
			end
			index = index % #options + 1
			for _, option in options do
				option.attrs.selected = nil
			end
			options[index].attrs.selected = ""
			local value = options[index].attrs.value or Html.flattenText(options[index])
			node.value = value
			self:setInput(node, value)
			self:dispatch(node, "change", { value = value })
		end
	elseif inputType == "radio" then
		node.checked = true
		local name = node.attrs.name
		if name and node.parent then
			for _, sibling in node.parent.children do
				if sibling ~= node and sibling.type == "element" and sibling.tag == "input" and sibling.attrs.name == name and (sibling.attrs.type or ""):lower() == "radio" then
					sibling.checked = false
				end
			end
		end
		self:invalidate()
		self:dispatch(node, "input")
		self:dispatch(node, "change")
	elseif inputType == "checkbox" then
		node.checked = not node.checked
		self:invalidate()
		self:dispatch(node, "input")
		self:dispatch(node, "change")
	end
	self:dispatch(node, "click")
end

function Web:setInput(node, value)
	node.value = tostring(value)
	self:dispatch(node, "input", { value = node.value })
	if self.config.onInput then
		pcall(self.config.onInput, node, node.value)
	end
end

function Web:submit(node, value)
	if value ~= nil then
		node.value = tostring(value)
	end
	self:dispatch(node, "submit", { value = node.value })
end

function Web:beginDrag(node, input)
	if not input or input.UserInputType ~= Enum.UserInputType.MouseButton1 then
		return
	end
	local userInputService = game:GetService("UserInputService")
	local startMouse = userInputService:GetMouseLocation()
	local start = self.position:get()
	local changedConnection
	local endedConnection

	changedConnection = userInputService.InputChanged:Connect(function(changed)
		if changed.UserInputType ~= Enum.UserInputType.MouseMovement then
			return
		end
		local mouse = userInputService:GetMouseLocation()
		self.position:set(UDim2.new(
			start.X.Scale,
			start.X.Offset + (mouse.X - startMouse.X),
			start.Y.Scale,
			start.Y.Offset + (mouse.Y - startMouse.Y)
		))
	end)

	endedConnection = userInputService.InputEnded:Connect(function(finished)
		local isMouse = finished == input or (finished and finished.UserInputType == Enum.UserInputType.MouseButton1)
		if isMouse then
			if changedConnection then
				changedConnection:Disconnect()
			end
			if endedConnection then
				endedConnection:Disconnect()
			end
		end
	end)
end

function Web:close()
	if self.closed then
		return
	end
	self.closed = true
	if self.handle then
		self.handle:unmount()
	end
	if self.gui then
		self.gui:Destroy()
	end
	if self.config.onClose then
		pcall(self.config.onClose)
	end
end

function Web:indexBoxes(box)
	self.boxById[box.node.id] = box
	for _, child in box.children do
		self:indexBoxes(child)
	end
end

function Web:view()
	local version = self.version:get()
	local minimized = self.minimized:get()
	local position = self.position:get()
	local toasts = self.toasts:get()

	if minimized then
		return Components.button({
			key = "rauri-restore",
			width = 168,
			height = 34,
			anchor = { 0.5, 0.5 },
			position = UDim2.new(0.5, 0, 0.5, 0),
			text = "Rauri - restore",
			style = {
				bg = self:var("surface-alt"),
				fg = self:var("text"),
				font = "medium",
				fontSize = 12,
				radius = 999,
				border = { 1, self:var("border") },
				pad = { 14, 7 },
			},
			onClick = function()
				self.minimized:set(false)
			end,
		})
	end

	self.boxById = {}
	local computed = Css.compute(self.document, self.stylesheet, {})
	local root = Layout.build(self.document, computed, self.width, self.height)
	self:indexBoxes(root)

	local page = Render.box(root, root.x, root.y, self)
	local toastNodes = {}
	for index, toast in toasts do
		toastNodes[#toastNodes + 1] = Components.frame({
			key = "toast-" .. tostring(toast.id),
			width = 260,
			height = 34,
			anchor = { 1, 1 },
			position = UDim2.new(1, -14, 1, -14 - (#toastNodes * 42)),
			zIndex = 200,
			style = {
				bg = self:var("surface-alt"),
				radius = 8,
				border = { 1, self:var("border") },
				pad = 0,
			},
		}, {
			Components.text({
				key = "toast-text-" .. tostring(toast.id),
				width = 260,
				height = 34,
				text = toast.message,
				style = {
					fg = self:var("text"),
					fontSize = 12,
					font = "medium",
					valign = "center",
					align = "center",
				},
			}),
		})
	end

	return Components.frame({
		key = "rauri-window",
		width = self.width,
		height = self.height,
		anchor = { 0.5, 0.5 },
		position = position,
		clip = true,
		zIndex = 10,
		style = {
			bg = self:var("bg"),
			radius = self.radius,
			border = { 1, self:var("border") },
		},
	}, {
