		local cached = inlineCache[node.inlineStyle]
		if not cached then
			cached = parseDeclarations(node.inlineStyle)
			inlineCache[node.inlineStyle] = cached
		end
		for _, declaration in cached do
			declarations[#declarations + 1] = declaration
		end
	end
