	local listeners = node.listeners[eventType]
	if not listeners then
		listeners = {}
		node.listeners[eventType] = listeners
	end
	listeners[#listeners + 1] = fn
	return function()
		for index, listener in listeners do
			if listener == fn then
				table.remove(listeners, index)
				break
			end
		end
	end
end

